import java.util.Arrays;
import java.util.Scanner;

public class p1096g_v1 {
    static final long MOD = 998244353;

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int k = in.nextInt();
        long[] base = new long[10];
        for (int i = 0; i < k; i++) {
            base[in.nextInt()] = 1;
        }
        long[] res = exponentiate(base, n / 2);
        long total = 0;
        for (long val : res) {
            total = (total + (val * val) % MOD) % MOD;
        }
        System.out.println(total);
    }

    static long[] exponentiate(long[] base, long exp) {
        if (exp == 1) return base;
        if ((exp & 1) == 1) {
            return FFT.multiplyPrecise(base, exponentiate(base, exp - 1));
        }
        long[] half = exponentiate(base, exp >> 1);
        return FFT.multiplyPrecise(half, half);
    }

    static class FFT {
        static final int MAX_K = 21;
        static final int MAX_N = 1 << MAX_K;
        static double[] wR = new double[MAX_N],
                wI = new double[MAX_N],
                rR = new double[MAX_N],
                rI = new double[MAX_N],
                aR = new double[MAX_N],
                aI = new double[MAX_N];
        static int n, k, lastK = -1;
        static int[] bitReverse = new int[MAX_N];

        static void performFFT(boolean inverse) {
            if (lastK != k) {
                lastK = k;
                bitReverse[0] = 0;
                for (int i = 1, group = -1; i < n; i++) {
                    if ((i & (i - 1)) == 0) group++;
                    bitReverse[i] = bitReverse[i ^ (1 << group)] ^ (1 << (k - 1 - group));
                }
                wR[1] = 1;
                wI[1] = 0;
                for (int t = 0; t < k - 1; t++) {
                    double angle = Math.PI / n * (1 << (k - 1 - t));
                    double cosVal = Math.cos(angle);
                    double sinVal = Math.sin(angle);
                    int p2 = 1 << t;
                    int p3 = p2 << 1;
                    for (int j = p2, idx = j * 2; j < p3; j++, idx += 2) {
                        wR[idx] = wR[j];
                        wI[idx] = wI[j];
                        wR[idx + 1] = wR[j] * cosVal - wI[j] * sinVal;
                        wI[idx + 1] = wR[j] * sinVal + wI[j] * cosVal;
                    }
                }
            }
            for (int i = 0; i < n; i++) {
                int rev = bitReverse[i];
                if (i < rev) {
                    double temp = aR[i];
                    aR[i] = aR[rev];
                    aR[rev] = temp;
                    temp = aI[i];
                    aI[i] = aI[rev];
                    aI[rev] = temp;
                }
            }
            if (inverse) {
                for (int i = 0; i < n; i++) aI[i] = -aI[i];
            }
            for (int len = 1; len < n; len <<= 1) {
                for (int i = 0; i < n; i += len) {
                    int wIndex = len;
                    for (int it = 0, j = i + len; it < len; it++, i++, j++) {
                        double realPart = aR[j] * wR[wIndex] - aI[j] * wI[wIndex];
                        double imagPart = aR[j] * wI[wIndex] + aI[j] * wR[wIndex];
                        wIndex++;
                        aR[j] = aR[i] - realPart;
                        aI[j] = aI[i] - imagPart;
                        aR[i] += realPart;
                        aI[i] += imagPart;
                    }
                }
            }
        }

        static long[] multiply(long[] first, long[] second) {
            int len1 = first.length, len2 = second.length;
            for (k = 0, n = 1; n < len1 + len2 - 1; n <<= 1, k++) {}
            for (int i = 0; i < n; i++) {
                aR[i] = (i < len1) ? first[i] : 0;
                aI[i] = (i < len2) ? second[i] : 0;
            }
            performFFT(false);
            aR[n] = aR[0];
            aI[n] = aI[0];
            double factor = -1.0 / n / 4.0;
            for (int i = 0; i <= n - i; i++) {
                double real1 = aR[i] * aR[i] - aI[i] * aI[i];
                double imag1 = aR[i] * aI[i] * 2;
                double real2 = aR[n - i] * aR[n - i] - aI[n - i] * aI[n - i];
                double imag2 = aR[n - i] * aI[n - i] * -2;
                double newReal = -imag1 + imag2;
                double newImag = real1 - real2;
                aR[i] = newReal * factor;
                aI[i] = newImag * factor;
                aR[n - i] = aR[i];
                aI[n - i] = -aI[i];
            }
            performFFT(true);
            long[] result = new long[len1 + len2 - 1];
            for (int i = 0; i < result.length; i++) {
                result[i] = Math.round(aR[i]) % MOD;
            }
            return result;
        }

        static long[] multiplyPrecise(long[] first, long[] second) {
            long sqrtMod = (long) Math.sqrt(MOD);
            long[] aLow = new long[first.length];
            long[] aHigh = new long[first.length];
            long[] bLow = new long[second.length];
            long[] bHigh = new long[second.length];
            for (int i = 0; i < first.length; i++) {
                aLow[i] = first[i] % sqrtMod;
                aHigh[i] = first[i] / sqrtMod;
            }
            for (int i = 0; i < second.length; i++) {
                bLow[i] = second[i] % sqrtMod;
                bHigh[i] = second[i] / sqrtMod;
            }
            long[] r11 = multiply(aLow, bLow);
            long[] r12 = multiply(aLow, bHigh);
            long[] r21 = multiply(aHigh, bLow);
            long[] r22 = multiply(aHigh, bHigh);
            long[] result = new long[r11.length];
            for (int i = 0; i < result.length; i++) {
                result[i] = ((sqrtMod * sqrtMod % MOD) * r22[i] % MOD +
                        (sqrtMod * ((r12[i] + r21[i]) % MOD)) % MOD +
                        r11[i]) % MOD;
            }
            return result;
        }
    }
}
